private fun ev(
    id: String,
    brand: String,
    model: String,
    category: VehicleCategory,
    era: String,
    modelYear: Int,
    horsepower: Double,
    maxSpeedKmh: Double,
    weightKg: Double,
    priceBrl: Double,
    bodyStyle: VehicleBodyStyle,
    wheelLayout: WheelLayout,
    primaryColorRgb: RgbTriple,
    accentColorRgb: RgbTriple,
    dimensionsM: DimTriple,
    supportedHitches: List<HitchType>,
    tankCapacityL: Double,
    soundProfile: String,
    subTypeLabel: String,
    description: String,
    requiredModPackId: String? = null,
): VehicleDef {
    val hasGrainTank = tankCapacityL > 0.0
    val maxTorqueNm = (horsepower * if (category == VehicleCategory.CAMINHAO) 4.4 else 3.9).roundToInt().toDouble()
    val fuelCapacityL = max(
        95.0,
        (horsepower * if (category == VehicleCategory.COLHEITADEIRA) 2.1 else 1.35).roundToInt().toDouble(),
    )
    val turnRateDegPerSec = when (bodyStyle) {
        VehicleBodyStyle.TRUCK -> 40.0
        VehicleBodyStyle.HARVESTER -> 34.0
        VehicleBodyStyle.SKID_STEER, VehicleBodyStyle.FORKLIFT -> 76.0
        else -> 48.0
    }
    return VehicleDef(
        id = id,
        brand = brand,
        model = model,
        category = category,
        era = era,
        modelYear = modelYear,
        horsepower = horsepower,
        maxTorqueNm = maxTorqueNm,
        maxSpeedKmh = maxSpeedKmh,
        fuelCapacityL = fuelCapacityL,
        weightKg = weightKg,
        priceBrl = priceBrl,
        supportedHitches = supportedHitches,
        primaryColorRgb = primaryColorRgb,
        accentColorRgb = accentColorRgb,
        bodyStyle = bodyStyle,
        wheelLayout = wheelLayout,
        hasCab = bodyStyle != VehicleBodyStyle.MOTO,
        dimensionsM = dimensionsM,
        turnRateDegPerSec = turnRateDegPerSec,
        soundProfile = soundProfile,
        hasGrainTank = hasGrainTank,
        tankCapacityL = tankCapacityL,
        gpsReady = modelYear >= 2014,
        description = description,
        requiredModPackId = requiredModPackId,
        subTypeLabel = subTypeLabel,
    )
}

